def bbox(g):
    rows=[i for i,r in enumerate(g) if any(x!=0 for x in r)]
    cls=[j for j in range(len(g[0])) if any(r[j]!=0 for r in g)]
    return min(rows),max(rows),min(cls),max(cls)
